        fn sim(
            &self,
            clock_reset: rhdl::core::ClockReset,
            input: <Self as SynchronousIO>::I,
            state: &mut Self::S,
        ) -> <Self as SynchronousIO>::O {
            let update_fn = <<Self as SynchronousIO>::Kernel as DigitalFn3>::func();
            rhdl::core::trace("input", &input);
            for _ in 0..rhdl::core::MAX_ITERS {
                let prev_state = state.clone();
                let (outputs, internal_inputs) = update_fn(clock_reset, input, state.0);
                rhdl::core::trace_push_path("regs");
                state.0.regs = self
                    .regs
                    .sim(clock_reset, internal_inputs.regs, &mut state.1);
                rhdl::core::trace_pop_path();
                rhdl::core::trace_push_path("T1");
                state.0.T1 = self.T1.sim(clock_reset, internal_inputs.T1, &mut state.2);
                rhdl::core::trace_pop_path();
                rhdl::core::trace_push_path("T2");
                state.0.T2 = self.T2.sim(clock_reset, internal_inputs.T2, &mut state.3);
                rhdl::core::trace_pop_path();
                rhdl::core::trace_push_path("MA");
                state.0.MA = self.MA.sim(clock_reset, internal_inputs.MA, &mut state.4);
                rhdl::core::trace_pop_path();
                rhdl::core::trace_push_path("PC");
                state.0.PC = self.PC.sim(clock_reset, internal_inputs.PC, &mut state.5);
                rhdl::core::trace_pop_path();
                rhdl::core::trace_push_path("IR");
                state.0.IR = self.IR.sim(clock_reset, internal_inputs.IR, &mut state.6);
                rhdl::core::trace_pop_path();
                rhdl::core::trace_push_path("FR");
                state.0.FR = self.FR.sim(clock_reset, internal_inputs.FR, &mut state.7);
                rhdl::core::trace_pop_path();
                rhdl::core::trace_push_path("Cu");
                state.0.Cu = self.Cu.sim(clock_reset, internal_inputs.Cu, &mut state.8);
                rhdl::core::trace_pop_path();
                rhdl::core::trace_push_path("RAM");
                state.0.RAM = self
                    .RAM
                    .sim(clock_reset, internal_inputs.RAM, &mut state.9);
                rhdl::core::trace_pop_path();
                if state == &prev_state {
                    rhdl::core::trace("outputs", &outputs);
                    return outputs;
                }
            }
            {
                ::core::panicking::panic_fmt(
                    format_args!("Simulation did not converge"),
                );
            };
        }
