        type S = <Cpu as Synchronous>::S;
        type O = <Cpu as SynchronousIO>::O;
        use colored::Colorize;
        fn rg(s: &S, i: usize) -> u128 {
            s.1.1[i].current.raw()
        }
        fn t1(s: &S) -> u128 {
            s.1.0;
            s.2.1.current.raw()
        }
        fn t2(s: &S) -> u128 {
            s.3.1.current.raw()
        }
        fn ma(s: &S) -> u128 {
            s.4.1.current.raw()
        }
